// In-memory stand-in for a database row. Lives outside Next.js's cache, which
// is why the action uses refresh() rather than revalidatePath()/updateTag().
type UserPreferences = {
  notificationsEnabled: boolean
}

const preferences: UserPreferences = {
  notificationsEnabled: false,
}

export async function getNotificationPreference(): Promise<boolean> {
  return preferences.notificationsEnabled
}

export async function setNotificationPreference(enabled: boolean): Promise<void> {
  preferences.notificationsEnabled = enabled
}

