import { connection } from 'next/server'
import { toggleNotifications } from '@/app/actions'
import { getNotificationPreference } from '@/app/lib/preferences'

export default async function Home() {
  // The preference is request-time state outside the cache, so make sure this
  // page renders per request instead of being prerendered once at build time.
  await connection()
  const notificationsEnabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently{' '}
        <strong>{notificationsEnabled ? 'on' : 'off'}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {notificationsEnabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

