cd /workspace; (npx next start -p 3123 > /tmp/next.log 2>&1 &); sleep 4; 
echo "--- initial page:"; curl -s http://localhost:3123/ | grep -o 'Notifications are currently.\{0,80\}' ;
ACTION=$(curl -s http://localhost:3123/ | grep -o 'name="\$ACTION_ID_[a-f0-9]*"' | head -1 | sed 's/name="\$ACTION_ID_//;s/"//'); echo "action id: $ACTION";
echo "--- after POST:"; curl -s -X POST http://localhost:3123/ -H "Origin: http://localhost:3123" -H "Next-Action: $ACTION" -H "Accept: text/x-component" -H "Content-Type: text/plain;charset=UTF-8" --data '[]' | grep -o 'Notifications are currently.\{0,80\}\|Turn notifications [a-z]*' | head -3;
echo "--- fresh GET:"; curl -s http://localhost:3123/ | grep -o 'Notifications are currently.\{0,80\}'; pkill -f "next start" ; true

